    inline bool NDArray<T>::point_in_range(size_t x, size_t y, size_t z) const
    {
        GADGET_DEBUG_CHECK_THROW(dimensions_.size()==3);
        return ( (x<dimensions_[0]) && (y<dimensions_[1]) && (z<dimensions_[2]));
    }

