        allocate_memory();
        if (cudaMemcpy(this->data_, a.get_data_ptr(), this->elements_*sizeof(T), cudaMemcpyHostToDevice) != cudaSuccess) {
            deallocate_memory();
            this->data_ = 0;
            this->dimensions_.clear();
        }
